<div class="section-heading"><div><div class="eyebrow">Comunicação</div><h1>Logs de automação</h1><p class="text-secondary mb-0">Histórico de retornos automáticos, e-mail e WhatsApp para saber o que foi enviado ou falhou.</p></div></div><a class="btn btn-light" href="/master/integrations">Configurações</a></div><div class="card mb-4"><div class="card-header"><strong>Automação de retorno</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Empresa</th><th>Cliente</th><th>Canal</th><th>Evento</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d/m/Y H:i',strtotime($r['created_at']))?></td><td><?=htmlspecialchars($r['tenant_name'])?></td><td><?=htmlspecialchars($r['customer_name'])?></td><td><?=htmlspecialchars($r['channel'])?></td><td><?=htmlspecialchars($r['event_type'])?></td><td><span class="badge text-bg-<?=$r['status']==='sent'?'success':($r['status']==='failed'?'danger':'warning')?>"><?=htmlspecialchars($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header"><strong>Notificações externas</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Data</th><th>Empresa</th><th>Cliente</th><th>Destino</th><th>Status</th><th>Erro</th></tr></thead><tbody><?php foreach($notifications as $n):?><tr><td><?=date('d/m/Y H:i',strtotime($n['created_at']))?></td><td><?=htmlspecialchars($n['tenant_name'])?></td><td><?=htmlspecialchars($n['customer_name']??'-')?></td><td><?=htmlspecialchars($n['channel'].' · '.($n['destination']??''))?></td><td><?=htmlspecialchars($n['status'])?></td><td><?=htmlspecialchars($n['error_message']??'')?></td></tr><?php endforeach;?></tbody></table></div></div>
